head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


window.onload = function() {
    scwin.fn_datepicker();
};
/**
 * @method
 * @name fn_datepicker
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_datepicker = function() {
    $(".datepicker").datepicker({
        dateFormat: 'yymmdd',
        monthNamesShort: ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'],
        dayNamesMin: ['일', '월', '화', '수', '목', '금', '토'],
        weekheader: 'Wk',
        changeMonth: true, //월변경가능	
        changeYear: true, //년변경가능	
        showMonthAfterYear: true, //년 뒤에 월 표시	
        buttonImageOnly: true, //이미지 표시	
        buttonText: '날짜를 선택하세요',
        buttonImageOnly: true,
        buttonImage: "/img/btn-cal-ico.png",
        autoSize: false,
        showOn: "button", //엘리먼트와 이미지 동시사용,	
        id: "test"
    });
    $('.datepicker').next().css("cursor", "pointer");
    $('.datepicker').next().css("margin-left", "6px");
};
